using System;using System.IO;using System.Linq;using System.Text.Json;using System.Text.Json.Nodes;using System.Collections.Generic;using System.Reflection;using Sdt.Core;using Sdt.Core.Battle;
class Audit {
 sealed class Host:BattleHost { public int Hp{get;set;}=30;public int MaxHp=>60;public int Atk=>4;public int SpellPower=>2;public string MyClass=>null;public string CharacterId=>"wu";public IReadOnlyList<OwnedCard> OwnedCards{get;set;}=Array.Empty<OwnedCard>();public void Log(string text,string kind=null){}public void Heal(int n){Hp=Math.Min(MaxHp,Hp+n);}public void OnBattleEnd(BattleResult r){} }
 static RuleValue Rule(JsonObject data){var r=new RuleValue();foreach(var p in data)r.Values[p.Key]=Value(p.Value);return r;}
 static object Value(JsonNode v){if(v==null)return null;if(v is JsonObject o)return Rule(o);if(v is JsonArray a)return a.Select(Value).ToArray();var r=(JsonValue)v;if(r.TryGetValue<int>(out var n))return n;if(r.TryGetValue<bool>(out var b))return b;if(r.TryGetValue<string>(out var s))return s;return r.GetValue<double>();}
 static object Field(BattleSession b,string n)=>typeof(BattleSession).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b);
 static void Main(){CardLibrary.Init(()=>CardDatabase.All);var rows=JsonNode.Parse(File.ReadAllText("source-round2-results.json")).AsArray();var result=new List<object>();foreach(var row in rows){var name=(string)row["name"];var owned=row["input"].AsArray().Select(n=>{var c=n["card"].Deserialize<CardDef>(new JsonSerializerOptions{IncludeFields=true});c.rules=n["card"]["rules"] is JsonObject r?Rule(r):null;return new OwnedCard{uid=(string)n["uid"],card=c};}).ToArray();var host=new Host{OwnedCards=owned};var b=new BattleSession();var foes=(name=="scale"||name=="dart")?new[]{new EnemyInput{id="foe",name="目标",hp=100,atk=2},new EnemyInput{id="other",name="另一个目标",hp=100,atk=2}}:new[]{new EnemyInput{id="foe",name="目标",hp=100,atk=2}};if(name=="provoke")foes=new[]{new EnemyInput{id="foe",name="目标",hp=100,atk=2},new EnemyInput{id="other",name="另一个目标",hp=100,atk=2},new EnemyInput{id="third",name="第三目标",hp=100,atk=6}};b.Start(new BattleStartContext{host=host,rng=new Rng(name=="scale"?1u:123u),isBoss=name.EndsWith("-boss"),enemies=foes});if(name.EndsWith("-boss")){foreach(var e in owned)if(e.card.id!="starter-attack")b.SelectDeckCard(e.uid);b.ConfirmDeck();var hand=(List<string>)Field(b,"hand");hand.Clear();hand.AddRange(owned.Select(o=>o.uid));((List<string>)Field(b,"drawPile")).RemoveAll(uid=>owned.Any(o=>o.uid==uid));}var command=b.PlayCard("o0",new[]{"immortal","dart","fuel"}.Contains(name)?0:name=="provoke"?1:-1,false);var firstHand=b.Snapshot.Hand.ToArray();if(name=="immortal")command=b.PlayCard("o0",0,false);if(name=="fuel")b.SelectInfusion("o1");if(name=="scale")b.EndTurn();result.Add(new{name,ok=command.Ok,reason=command.Reason,firstHand,picked=b.Snapshot.Infusing?.Picked,hand=b.Snapshot.Hand.Select(uid=>b.FindCard(uid).card.id).ToArray(),consumed=((List<string>)Field(b,"consumed")).ToArray(),armor=b.Snapshot.Pdef.Armor,foes=b.Snapshot.Foes.Select(e=>new{e.id,e.hp,bleed=e.status["bleed"],poison=e.status["poison"]}).ToArray(),energy=b.Snapshot.Energy,hp=host.Hp});b.Retract();}File.WriteAllText("core-round2-results.json",JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(File.ReadAllText("core-round2-results.json"));}
}


